using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using Nickelony.Stanza.Analyzers.BlankLines;
using Nickelony.Stanza.Tests.Shared;

namespace Nickelony.Stanza.Analyzers.Tests;

[TestClass]
public sealed class GeneratedCodeTests
{
	public static IEnumerable<object[]> GeneratedSources { get; } =
	[
		[
			"a repeated statement run",

			"""
				// <auto-generated/>
				class C
				{
					void M()
					{
						var value = 1;
						DoThing();
						DoThing();
						return;
					}
				}
				""",
		],

		[
			"a multi-line construct",

			"""
				// <auto-generated/>
				class C
				{
					void M()
					{
						if (true)
						{
							DoThing();
						}
						DoThing();
					}
				}
				""",
		],

		[
			"a padded brace",

			"""
				// <auto-generated/>
				class C
				{
					void M()
					{

						DoThing();

					}
				}
				""",
		],

		[
			"a multi-line expression body",

			"""
				// <auto-generated/>
				class C
				{
					int Pick(bool first) =>
						first ? 1
						: 2;
				}
				""",
		],

		[
			"a #line hidden region",

			"""
				#line hidden
				class C
				{
					void M()
					{
						var value = 1;
						DoThing();
						DoThing();
						return;
					}
				}
				#line default
				""",
		],
	];

	// Roslyn owns the list of generated names, so one of them stands for the rest.
	[TestMethod]
	[CrossCutting]
	public async Task AGeneratedFileNameIsNeverInspected()
	{
		const string fileName = "Test.Designer.cs";

		const string source = """
			class C
			{
				void M()
				{
					var value = 1;
					DoThing();
					DoThing();
					return;
				}
			}
			""";

		Assert.IsEmpty(
			await RoslynTestHarness.RunNamedAsync<SeparateDeclarationAndInvocationRunsAnalyzer>(
				source,
				fileName
			),

			$"'{fileName}' is a generated file name."
		);

		Assert.IsNotEmpty(
			await RoslynTestHarness.RunNamedAsync<SeparateDeclarationAndInvocationRunsAnalyzer>(
				source,
				"Test.cs"
			),

			"the same body reports under an ordinary file name."
		);
	}

	[TestMethod]
	public async Task AnAnalyzerConfigThatMarksAFileGeneratedSilencesIt()
	{
		const string source = """
			class C
			{
				void M()
				{
					var value = 1;
					DoThing();
					DoThing();
					return;
				}
			}
			""";

		AnalyzerRunResult result = await RoslynTestHarness.ReportAllAsync(
			source,
			analyzerConfigOptions: new Dictionary<string, string> { ["generated_code"] = "true" }
		);

		Assert.IsEmpty(
			result.Diagnostics,
			"a rule reported inside a file the config marks as generated."
		);

		Assert.IsNotEmpty(
			(await RoslynTestHarness.ReportAllAsync(source)).Diagnostics,
			"the same body reports while the option is not set."
		);
	}

	[TestMethod]
	[DynamicData(
		nameof(GeneratedSources),
		DynamicDataDisplayName = nameof(RowNames.GetRowName),
		DynamicDataDisplayNameDeclaringType = typeof(RowNames)
	)]
	public async Task AnAutoGeneratedFileIsNeverInspected(string name, string source)
	{
		AnalyzerRunResult result = await RoslynTestHarness.RunAllAsync(
			source,
			TestRuleSets.AllRulesEnabled
		);

		Assert.IsEmpty(
			result.Diagnostics,
			$"{name}: a rule reported inside a file that is marked as generated."
		);
	}

	[TestMethod]
	[DynamicData(
		nameof(GeneratedSources),
		DynamicDataDisplayName = nameof(RowNames.GetRowName),
		DynamicDataDisplayNameDeclaringType = typeof(RowNames)
	)]
	public async Task EachGeneratedSourceReportsOnceItsMarkerIsGone(string name, string source)
	{
		string ordinary = source
			.Replace("// <auto-generated/>", "// written by hand", StringComparison.Ordinal)
			.Replace("#line hidden", "#line default", StringComparison.Ordinal);

		AnalyzerRunResult result = await RoslynTestHarness.ReportAllAsync(
			ordinary,
			TestRuleSets.AllRulesEnabled
		);

		Assert.IsNotEmpty(
			result.Diagnostics,
			$"{name}: nothing reports without the marker, so the silence above proves nothing."
		);
	}

	[TestMethod]
	public async Task TheSameBodyReportsOnceItsMarkerIsGone()
	{
		const string source = """
			class C
			{
				void M()
				{
					var value = 1;
					DoThing();
					DoThing();
					return;
				}
			}
			""";

		AnalyzerRunResult result = await RoslynTestHarness.ReportAllAsync(
			source,
			TestRuleSets.AllRulesEnabled
		);

		Assert.Contains(
			DiagnosticDescriptors.SeparateDeclarationAndInvocationRuns.Id,
			result.Diagnostics.Select(diagnostic => diagnostic.Id),
			"The body reports even without the marker, so the silence above proves nothing."
		);
	}
}
